arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project is already scaffolded at `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/` with Interactive Auto, Global interactivity, and Individual auth.

The solution has two projects:
- `ShipmentTracker` (server) - hosts app, APIs, EF Core, Identity
- `ShipmentTracker.Client` (WebAssembly) - all interactive UI components

## What to implement

### 1. Shared Model (in `.Client` project since both projects reference it)

Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker.Client/Models/Shipment.cs`:

```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty; // Pending, InTransit, Delivered, Delayed
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

### 2. Service Interface (in `.Client` project)

Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker.Client/Services/IShipmentService.cs`:

```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail);
    Task UpdateShipmentStatusAsync(int id, string status);
}
```

### 3. Client-side implementation (HttpClient-based, in `.Client` project)

Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker.Client/Services/ShipmentHttpService.cs`:

```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(customerEmail)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
    }
}
```

### 4. Server-side implementation (EF Core, in server project)

First, create the EF entity. Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker/Data/ShipmentEntity.cs`:

```csharp
namespace ShipmentTracker.Data;

public class ShipmentEntity
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

Edit `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker/Data/ApplicationDbContext.cs` to add a `DbSet<ShipmentEntity>` property.

Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker/Services/ShipmentServerService.cs`:

```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.Select(e => ToModel(e)).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToModel(entity);
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == customerEmail)
            .Select(e => ToModel(e))
            .ToListAsync();
    }

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = status;
            await db.SaveChangesAsync();
        }
    }

    private static Shipment ToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        CustomerEmail = e.CustomerEmail,
        Description = e.Description
    };
}
```

### 5. API Endpoints (in server Program.cs)

Add minimal API endpoints after `app.MapAdditionalIdentityEndpoints();`:

```csharp
app.MapGet("api/shipments", async (ShipmentServerService service) =>
    await service.GetAllShipmentsAsync()).RequireAuthorization();

app.MapGet("api/shipments/track/{trackingNumber}", async (string trackingNumber, ShipmentServerService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapGet("api/shipments/customer/{email}", async (string email, ShipmentServerService service) =>
    await service.GetShipmentsByCustomerAsync(email)).RequireAuthorization();

app.MapPut("api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ShipmentServerService service) =>
{
    await service.UpdateShipmentStatusAsync(id, request.Status);
    return Results.NoContent();
}).RequireAuthorization();
```

Also add record at the bottom of Program.cs (or in a separate file):
```csharp
public record StatusUpdateRequest(string Status);
```

And register services in server Program.cs (after the DbContext registration):
```csharp
builder.Services.AddScoped<ShipmentServerService>();
builder.Services.AddScoped<IShipmentService>(sp => sp.GetRequiredService<ShipmentServerService>());
```

### 6. Client Program.cs — register HttpClient and client service

Edit `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker.Client/Program.cs` to add:
```csharp
using ShipmentTracker.Client.Services;

// ... after existing service registrations:
builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();
```

### 7. Seed data

Create `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker/Data/SeedData.cs`:

```csharp
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static void Initialize(ApplicationDbContext db)
    {
        db.Database.Migrate();

        if (db.Shipments.Any()) return;

        db.Shipments.AddRange(
            new ShipmentEntity { TrackingNumber = "TRK-001", Origin = "New York, USA", Destination = "London, UK", Status = "InTransit", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com", Description = "Electronics package" },
            new ShipmentEntity { TrackingNumber = "TRK-002", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = "Pending", ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(10), CustomerEmail = "bob@example.com", Description = "Furniture shipment" },
            new ShipmentEntity { TrackingNumber = "TRK-003", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = "Delivered", ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "alice@example.com", Description = "Auto parts" },
            new ShipmentEntity { TrackingNumber = "TRK-004", Origin = "Sydney, Australia", Destination = "Dubai, UAE", Status = "Delayed", ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "carol@example.com", Description = "Clothing batch" },
            new ShipmentEntity { TrackingNumber = "TRK-005", Origin = "São Paulo, Brazil", Destination = "Paris, France", Status = "InTransit", ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "bob@example.com", Description = "Food products" }
        );

        db.SaveChanges();
    }
}
```

In server `Program.cs`, after `var app = builder.Build();` add:
```csharp
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    SeedData.Initialize(db);
}
```

### 8. Pages (in `.Client/Pages/`)

Delete Counter.razor, Weather.razor, and Auth.razor from `/tmp/sv-a21b4b68c24c428090aa32afc6bbf7f7/ShipmentTracker/ShipmentTracker.Client/Pages/`.

Keep Home.razor but rewrite it.

**Home.razor** — landing page:
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>
<p>Welcome to the logistics shipment tracking system.</p>

