    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(customerEmail)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
    }
}
